CREATE TABLE IF NOT EXISTS "customers" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Externally quotable customer number. Never reuse one, even after closure.
	"customer_reference" VARCHAR(24) NOT NULL UNIQUE,
	-- Name as it appears on identity documents.
	"legal_name" VARCHAR(200) NOT NULL,
	-- Required for individuals, null for corporate customers.
	"date_of_birth" DATE,
	-- Contact address for statements and alerts.
	"email" VARCHAR(320) NOT NULL,
	-- E.164 number used for step-up authentication.
	"phone" VARCHAR(32),
	-- pending | verified | rejected | review. Accounts cannot leave restricted status until this is verified.
	"kyc_status" VARCHAR(24) NOT NULL DEFAULT 'pending',
	-- When identity verification completed.
	"kyc_verified_at" TIMESTAMP,
	-- low | medium | high, from onboarding screening. Drives monitoring thresholds.
	"risk_rating" VARCHAR(16),
	-- Onboarding time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- Relationship closure. Rows are retained for the statutory period, never deleted.
	"closed_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "customers" IS 'The legal party the bank has a relationship with. Customers are never hard-deleted: retention periods for financial records outlast the account itself.';
COMMENT ON COLUMN "customers"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "customers"."customer_reference" IS 'Externally quotable customer number. Never reuse one, even after closure.';
COMMENT ON COLUMN "customers"."legal_name" IS 'Name as it appears on identity documents.';
COMMENT ON COLUMN "customers"."date_of_birth" IS 'Required for individuals, null for corporate customers.';
COMMENT ON COLUMN "customers"."email" IS 'Contact address for statements and alerts.';
COMMENT ON COLUMN "customers"."phone" IS 'E.164 number used for step-up authentication.';
COMMENT ON COLUMN "customers"."kyc_status" IS 'pending | verified | rejected | review. Accounts cannot leave restricted status until this is verified.';
COMMENT ON COLUMN "customers"."kyc_verified_at" IS 'When identity verification completed.';
COMMENT ON COLUMN "customers"."risk_rating" IS 'low | medium | high, from onboarding screening. Drives monitoring thresholds.';
COMMENT ON COLUMN "customers"."created_at" IS 'Onboarding time.';
COMMENT ON COLUMN "customers"."closed_at" IS 'Relationship closure. Rows are retained for the statutory period, never deleted.';

CREATE TABLE IF NOT EXISTS "accounts" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- IBAN or domestic account number shown to the customer.
	"account_number" VARCHAR(34) NOT NULL UNIQUE,
	-- checking | savings | loan | card | internal. Internal accounts are the bank side of every double-entry pair.
	"account_type" VARCHAR(24) NOT NULL,
	-- ISO 4217. An account holds exactly one currency; multi-currency means multiple accounts.
	"currency_code" CHAR(3) NOT NULL,
	-- active | frozen | dormant | closed.
	"status" VARCHAR(24) NOT NULL DEFAULT 'active',
	-- Cached balance in minor units, maintained by the same transaction that writes ledger entries. The ledger, not this column, is the source of truth.
	"balance_minor" BIGINT NOT NULL DEFAULT 0,
	-- Balance less pending authorizations and holds. This is what the ATM checks.
	"available_minor" BIGINT NOT NULL DEFAULT 0,
	-- Account opening date.
	"opened_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- Closure date. A closed account keeps its history and must net to zero.
	"closed_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "accounts" IS 'An account is a balance in one currency. Customer-facing and internal accounts share the table so that every movement of money has a debit account and a credit account inside the same ledger.';
COMMENT ON COLUMN "accounts"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "accounts"."account_number" IS 'IBAN or domestic account number shown to the customer.';
COMMENT ON COLUMN "accounts"."account_type" IS 'checking | savings | loan | card | internal. Internal accounts are the bank side of every double-entry pair.';
COMMENT ON COLUMN "accounts"."currency_code" IS 'ISO 4217. An account holds exactly one currency; multi-currency means multiple accounts.';
COMMENT ON COLUMN "accounts"."status" IS 'active | frozen | dormant | closed.';
COMMENT ON COLUMN "accounts"."balance_minor" IS 'Cached balance in minor units, maintained by the same transaction that writes ledger entries. The ledger, not this column, is the source of truth.';
COMMENT ON COLUMN "accounts"."available_minor" IS 'Balance less pending authorizations and holds. This is what the ATM checks.';
COMMENT ON COLUMN "accounts"."opened_at" IS 'Account opening date.';
COMMENT ON COLUMN "accounts"."closed_at" IS 'Closure date. A closed account keeps its history and must net to zero.';

CREATE INDEX "idx_accounts_type_status"
ON "accounts" ("account_type", "status");

CREATE TABLE IF NOT EXISTS "account_holders" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Account being held.
	"account_id" BIGINT NOT NULL,
	-- Holder.
	"customer_id" BIGINT NOT NULL,
	-- primary | joint | authorized_signatory | beneficial_owner.
	"relationship" VARCHAR(24) NOT NULL DEFAULT 'primary',
	-- When this party was attached to the account.
	"added_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- When the party was detached. Kept for audit rather than deleted.
	"removed_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "account_holders" IS 'Many-to-many between customers and accounts. Joint accounts and corporate signatories make this a relationship table rather than a customer_id column on accounts.';
COMMENT ON COLUMN "account_holders"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "account_holders"."account_id" IS 'Account being held.';
COMMENT ON COLUMN "account_holders"."customer_id" IS 'Holder.';
COMMENT ON COLUMN "account_holders"."relationship" IS 'primary | joint | authorized_signatory | beneficial_owner.';
COMMENT ON COLUMN "account_holders"."added_at" IS 'When this party was attached to the account.';
COMMENT ON COLUMN "account_holders"."removed_at" IS 'When the party was detached. Kept for audit rather than deleted.';

CREATE UNIQUE INDEX "uq_account_holders_account_customer"
ON "account_holders" ("account_id", "customer_id");

CREATE TABLE IF NOT EXISTS "transactions" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Idempotency key from the initiating system. A replayed request finds this row instead of posting twice.
	"transaction_reference" VARCHAR(40) NOT NULL UNIQUE,
	-- transfer | card_purchase | fee | interest | reversal | adjustment.
	"transaction_type" VARCHAR(32) NOT NULL,
	-- pending | posted | reversed. Reversal appends a mirrored transaction; posted rows are never edited.
	"status" VARCHAR(24) NOT NULL DEFAULT 'posted',
	-- Narrative shown on the statement.
	"description" VARCHAR(255),
	-- Set when this transaction reverses an earlier one, giving a linked audit chain.
	"reversal_of_id" BIGINT,
	-- Date the money counts for interest, which is not always the booking date.
	"value_date" DATE NOT NULL,
	-- When the entries were written.
	"booked_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "transactions" IS 'The journal header. One transaction owns two or more ledger entries whose signed amounts must sum to zero — that invariant is the whole point of the design.';
COMMENT ON COLUMN "transactions"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "transactions"."transaction_reference" IS 'Idempotency key from the initiating system. A replayed request finds this row instead of posting twice.';
COMMENT ON COLUMN "transactions"."transaction_type" IS 'transfer | card_purchase | fee | interest | reversal | adjustment.';
COMMENT ON COLUMN "transactions"."status" IS 'pending | posted | reversed. Reversal appends a mirrored transaction; posted rows are never edited.';
COMMENT ON COLUMN "transactions"."description" IS 'Narrative shown on the statement.';
COMMENT ON COLUMN "transactions"."reversal_of_id" IS 'Set when this transaction reverses an earlier one, giving a linked audit chain.';
COMMENT ON COLUMN "transactions"."value_date" IS 'Date the money counts for interest, which is not always the booking date.';
COMMENT ON COLUMN "transactions"."booked_at" IS 'When the entries were written.';

CREATE INDEX "idx_transactions_type_booked"
ON "transactions" ("transaction_type", "booked_at");

CREATE TABLE IF NOT EXISTS "ledger_entries" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Parent journal entry.
	"transaction_id" BIGINT NOT NULL,
	-- Account whose balance moves.
	"account_id" BIGINT NOT NULL,
	-- debit | credit. Stored explicitly so reports read naturally without interpreting a sign.
	"direction" VARCHAR(6) NOT NULL,
	-- Always positive, in minor units. Direction carries the sign.
	"amount_minor" BIGINT NOT NULL,
	-- Currency of the entry; must match the account currency.
	"currency_code" CHAR(3) NOT NULL,
	-- Account balance after this entry. Filled by the posting job so statements do not need a window function over all history.
	"running_balance_minor" BIGINT,
	-- Write time. Entries are append-only: corrections are new entries, never updates.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "ledger_entries" IS 'The immutable core. Every row is one side of a movement; the sum of amount_minor signed by direction across a transaction is zero, and the sum over an account is its balance.';
COMMENT ON COLUMN "ledger_entries"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "ledger_entries"."transaction_id" IS 'Parent journal entry.';
COMMENT ON COLUMN "ledger_entries"."account_id" IS 'Account whose balance moves.';
COMMENT ON COLUMN "ledger_entries"."direction" IS 'debit | credit. Stored explicitly so reports read naturally without interpreting a sign.';
COMMENT ON COLUMN "ledger_entries"."amount_minor" IS 'Always positive, in minor units. Direction carries the sign.';
COMMENT ON COLUMN "ledger_entries"."currency_code" IS 'Currency of the entry; must match the account currency.';
COMMENT ON COLUMN "ledger_entries"."running_balance_minor" IS 'Account balance after this entry. Filled by the posting job so statements do not need a window function over all history.';
COMMENT ON COLUMN "ledger_entries"."created_at" IS 'Write time. Entries are append-only: corrections are new entries, never updates.';

CREATE INDEX "idx_ledger_account_created"
ON "ledger_entries" ("account_id", "created_at");
CREATE INDEX "idx_ledger_transaction"
ON "ledger_entries" ("transaction_id");

CREATE TABLE IF NOT EXISTS "cards" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Account the card draws on.
	"account_id" BIGINT NOT NULL,
	-- Cardholder.
	"customer_id" BIGINT NOT NULL,
	-- Token from the card processor. The PAN itself is never stored.
	"card_reference" VARCHAR(40) NOT NULL UNIQUE,
	-- Last four digits, the only part of the number safe to display.
	"last_four" CHAR(4) NOT NULL,
	-- visa | mastercard | amex.
	"brand" VARCHAR(20) NOT NULL,
	-- Expiry date, first day of the month after validity ends.
	"expires_on" DATE NOT NULL,
	-- active | blocked | expired | cancelled.
	"status" VARCHAR(20) NOT NULL DEFAULT 'active',
	-- Issue date.
	"issued_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "cards" IS 'Cards store a processor token and the last four digits only. Keeping the full number out of the database removes the largest single item of PCI scope.';
COMMENT ON COLUMN "cards"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "cards"."account_id" IS 'Account the card draws on.';
COMMENT ON COLUMN "cards"."customer_id" IS 'Cardholder.';
COMMENT ON COLUMN "cards"."card_reference" IS 'Token from the card processor. The PAN itself is never stored.';
COMMENT ON COLUMN "cards"."last_four" IS 'Last four digits, the only part of the number safe to display.';
COMMENT ON COLUMN "cards"."brand" IS 'visa | mastercard | amex.';
COMMENT ON COLUMN "cards"."expires_on" IS 'Expiry date, first day of the month after validity ends.';
COMMENT ON COLUMN "cards"."status" IS 'active | blocked | expired | cancelled.';
COMMENT ON COLUMN "cards"."issued_at" IS 'Issue date.';

CREATE INDEX "idx_cards_account_status"
ON "cards" ("account_id", "status");

CREATE TABLE IF NOT EXISTS "card_authorizations" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Card presented.
	"card_id" BIGINT NOT NULL,
	-- Settlement transaction, set once the authorization clears. Null while pending.
	"transaction_id" BIGINT,
	-- Network authorization identifier, unique so a repeated network message cannot hold funds twice.
	"authorization_code" VARCHAR(32) NOT NULL UNIQUE,
	-- Merchant descriptor as sent by the network.
	"merchant_name" VARCHAR(160) NOT NULL,
	-- ISO 18245 MCC, used for spending categories and controls.
	"merchant_category_code" CHAR(4),
	-- Amount held, in minor units.
	"amount_minor" BIGINT NOT NULL,
	-- Currency of the authorization.
	"currency_code" CHAR(3) NOT NULL,
	-- pending | settled | expired | declined | reversed.
	"status" VARCHAR(20) NOT NULL DEFAULT 'pending',
	-- When the hold was placed.
	"authorized_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- When settlement posted to the ledger.
	"settled_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "card_authorizations" IS 'Pending holds. Authorizations reduce available_minor without touching balance_minor, which is exactly the gap customers see between "pending" and "posted" in their app.';
COMMENT ON COLUMN "card_authorizations"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "card_authorizations"."card_id" IS 'Card presented.';
COMMENT ON COLUMN "card_authorizations"."transaction_id" IS 'Settlement transaction, set once the authorization clears. Null while pending.';
COMMENT ON COLUMN "card_authorizations"."authorization_code" IS 'Network authorization identifier, unique so a repeated network message cannot hold funds twice.';
COMMENT ON COLUMN "card_authorizations"."merchant_name" IS 'Merchant descriptor as sent by the network.';
COMMENT ON COLUMN "card_authorizations"."merchant_category_code" IS 'ISO 18245 MCC, used for spending categories and controls.';
COMMENT ON COLUMN "card_authorizations"."amount_minor" IS 'Amount held, in minor units.';
COMMENT ON COLUMN "card_authorizations"."currency_code" IS 'Currency of the authorization.';
COMMENT ON COLUMN "card_authorizations"."status" IS 'pending | settled | expired | declined | reversed.';
COMMENT ON COLUMN "card_authorizations"."authorized_at" IS 'When the hold was placed.';
COMMENT ON COLUMN "card_authorizations"."settled_at" IS 'When settlement posted to the ledger.';

CREATE INDEX "idx_card_auth_card_status"
ON "card_authorizations" ("card_id", "status");

CREATE TABLE IF NOT EXISTS "beneficiaries" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Customer who saved the payee.
	"customer_id" BIGINT NOT NULL,
	-- Nickname chosen by the customer.
	"display_name" VARCHAR(160) NOT NULL,
	-- Destination account number or IBAN.
	"account_number" VARCHAR(34) NOT NULL,
	-- BIC, sort code or routing number, depending on the scheme.
	"bank_identifier" VARCHAR(20),
	-- Currency the payee is paid in.
	"currency_code" CHAR(3) NOT NULL,
	-- Confirmation-of-payee check. Unverified payees can be limited or delayed.
	"verified_at" TIMESTAMP,
	-- When the payee was saved.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "beneficiaries" IS 'Saved payees. External account details are stored as text because they belong to another institution and cannot be a foreign key.';
COMMENT ON COLUMN "beneficiaries"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "beneficiaries"."customer_id" IS 'Customer who saved the payee.';
COMMENT ON COLUMN "beneficiaries"."display_name" IS 'Nickname chosen by the customer.';
COMMENT ON COLUMN "beneficiaries"."account_number" IS 'Destination account number or IBAN.';
COMMENT ON COLUMN "beneficiaries"."bank_identifier" IS 'BIC, sort code or routing number, depending on the scheme.';
COMMENT ON COLUMN "beneficiaries"."currency_code" IS 'Currency the payee is paid in.';
COMMENT ON COLUMN "beneficiaries"."verified_at" IS 'Confirmation-of-payee check. Unverified payees can be limited or delayed.';
COMMENT ON COLUMN "beneficiaries"."created_at" IS 'When the payee was saved.';

CREATE UNIQUE INDEX "uq_beneficiaries_customer_account"
ON "beneficiaries" ("customer_id", "account_number");

CREATE TABLE IF NOT EXISTS "transfers" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Ledger transaction once posted. Null while the transfer is still being validated.
	"transaction_id" BIGINT,
	-- Account being debited.
	"source_account_id" BIGINT NOT NULL,
	-- Internal destination account. Null for outbound payments leaving the bank.
	"destination_account_id" BIGINT,
	-- Saved payee for an outbound payment.
	"beneficiary_id" BIGINT,
	-- Instructed amount, in minor units.
	"amount_minor" BIGINT NOT NULL,
	-- Currency instructed.
	"currency_code" CHAR(3) NOT NULL,
	-- internal | sepa | swift | ach | faster_payments.
	"scheme" VARCHAR(24) NOT NULL,
	-- submitted | screening | posted | rejected | returned.
	"status" VARCHAR(24) NOT NULL DEFAULT 'submitted',
	-- Execution date for a future-dated payment.
	"scheduled_for" DATE,
	-- When the instruction was received.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "transfers" IS 'The customer instruction, kept separate from the ledger transaction it produces. A transfer can sit in sanctions screening for hours before any money moves, and a rejected one must never have touched a balance.';
COMMENT ON COLUMN "transfers"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "transfers"."transaction_id" IS 'Ledger transaction once posted. Null while the transfer is still being validated.';
COMMENT ON COLUMN "transfers"."source_account_id" IS 'Account being debited.';
COMMENT ON COLUMN "transfers"."destination_account_id" IS 'Internal destination account. Null for outbound payments leaving the bank.';
COMMENT ON COLUMN "transfers"."beneficiary_id" IS 'Saved payee for an outbound payment.';
COMMENT ON COLUMN "transfers"."amount_minor" IS 'Instructed amount, in minor units.';
COMMENT ON COLUMN "transfers"."currency_code" IS 'Currency instructed.';
COMMENT ON COLUMN "transfers"."scheme" IS 'internal | sepa | swift | ach | faster_payments.';
COMMENT ON COLUMN "transfers"."status" IS 'submitted | screening | posted | rejected | returned.';
COMMENT ON COLUMN "transfers"."scheduled_for" IS 'Execution date for a future-dated payment.';
COMMENT ON COLUMN "transfers"."created_at" IS 'When the instruction was received.';

CREATE INDEX "idx_transfers_source_created"
ON "transfers" ("source_account_id", "created_at");
CREATE INDEX "idx_transfers_status"
ON "transfers" ("status");

CREATE TABLE IF NOT EXISTS "statements" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Account the statement covers.
	"account_id" BIGINT NOT NULL,
	-- First day covered.
	"period_start" DATE NOT NULL,
	-- Last day covered.
	"period_end" DATE NOT NULL,
	-- Balance carried in, in minor units.
	"opening_balance_minor" BIGINT NOT NULL,
	-- Balance carried out. Must equal opening plus the period movements.
	"closing_balance_minor" BIGINT NOT NULL,
	-- Object storage key for the rendered PDF.
	"document_key" VARCHAR(255),
	-- When the statement was produced.
	"generated_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "statements" IS 'Frozen period summaries. Statements are generated once and never recomputed, so a later correction appears as a new entry in the next period rather than silently changing a document the customer already downloaded.';
COMMENT ON COLUMN "statements"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "statements"."account_id" IS 'Account the statement covers.';
COMMENT ON COLUMN "statements"."period_start" IS 'First day covered.';
COMMENT ON COLUMN "statements"."period_end" IS 'Last day covered.';
COMMENT ON COLUMN "statements"."opening_balance_minor" IS 'Balance carried in, in minor units.';
COMMENT ON COLUMN "statements"."closing_balance_minor" IS 'Balance carried out. Must equal opening plus the period movements.';
COMMENT ON COLUMN "statements"."document_key" IS 'Object storage key for the rendered PDF.';
COMMENT ON COLUMN "statements"."generated_at" IS 'When the statement was produced.';

CREATE UNIQUE INDEX "uq_statements_account_period"
ON "statements" ("account_id", "period_start");

ALTER TABLE "account_holders"
ADD FOREIGN KEY("account_id") REFERENCES "accounts"("id")
ON UPDATE CASCADE ON DELETE RESTRICT;
ALTER TABLE "account_holders"
ADD FOREIGN KEY("customer_id") REFERENCES "customers"("id")
ON UPDATE CASCADE ON DELETE RESTRICT;
ALTER TABLE "transactions"
ADD FOREIGN KEY("reversal_of_id") REFERENCES "transactions"("id")
ON UPDATE CASCADE ON DELETE RESTRICT;
ALTER TABLE "ledger_entries"
ADD FOREIGN KEY("transaction_id") REFERENCES "transactions"("id")
ON UPDATE CASCADE ON DELETE RESTRICT;
ALTER TABLE "ledger_entries"
ADD FOREIGN KEY("account_id") REFERENCES "accounts"("id")
ON UPDATE CASCADE ON DELETE RESTRICT;
ALTER TABLE "cards"
ADD FOREIGN KEY("account_id") REFERENCES "accounts"("id")
ON UPDATE CASCADE ON DELETE RESTRICT;
ALTER TABLE "cards"
ADD FOREIGN KEY("customer_id") REFERENCES "customers"("id")
ON UPDATE CASCADE ON DELETE RESTRICT;
ALTER TABLE "card_authorizations"
ADD FOREIGN KEY("card_id") REFERENCES "cards"("id")
ON UPDATE CASCADE ON DELETE RESTRICT;
ALTER TABLE "card_authorizations"
ADD FOREIGN KEY("transaction_id") REFERENCES "transactions"("id")
ON UPDATE CASCADE ON DELETE SET NULL;
ALTER TABLE "beneficiaries"
ADD FOREIGN KEY("customer_id") REFERENCES "customers"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "transfers"
ADD FOREIGN KEY("transaction_id") REFERENCES "transactions"("id")
ON UPDATE CASCADE ON DELETE SET NULL;
ALTER TABLE "transfers"
ADD FOREIGN KEY("source_account_id") REFERENCES "accounts"("id")
ON UPDATE CASCADE ON DELETE RESTRICT;
ALTER TABLE "transfers"
ADD FOREIGN KEY("destination_account_id") REFERENCES "accounts"("id")
ON UPDATE CASCADE ON DELETE RESTRICT;
ALTER TABLE "transfers"
ADD FOREIGN KEY("beneficiary_id") REFERENCES "beneficiaries"("id")
ON UPDATE CASCADE ON DELETE SET NULL;
ALTER TABLE "statements"
ADD FOREIGN KEY("account_id") REFERENCES "accounts"("id")
ON UPDATE CASCADE ON DELETE RESTRICT;
